"""Candidate vs reference differential driver."""
import json, os, random, subprocess, sys
sys.path.insert(0, '/workspace/dev')
import gen, ref

CAND = '/workspace/submission/main.py'
ENV = dict(os.environ, PYTHONDONTWRITEBYTECODE='1')

def candidate_out(data):
    p = subprocess.run([sys.executable, '-B', CAND], input=data.encode(), stdout=subprocess.PIPE,
                       stderr=subprocess.PIPE, env=ENV)
    if p.returncode != 0:
        raise RuntimeError('candidate exit %d: %s' % (p.returncode, p.stderr[:600]))
    if p.stderr.strip():
        raise RuntimeError('candidate stderr: %s' % p.stderr[:600])
    return p.stdout.decode()

def norm(x):
    if isinstance(x, dict):
        return {k: norm(v) for k, v in x.items()}
    if isinstance(x, list):
        return [norm(v) for v in x]
    if isinstance(x, float):
        raise AssertionError('float in output %r' % x)
    return x

def diff(a, b, path=''):
    if isinstance(a, dict) and isinstance(b, dict):
        if set(a) != set(b):
            return path + ' keys %s vs %s' % (sorted(a), sorted(b))
        for k in a:
            r = diff(a[k], b[k], path + '/' + k)
            if r: return r
        return None
    if isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return '%s len %d vs %d' % (path, len(a), len(b))
        for i, (x, y) in enumerate(zip(a, b)):
            r = diff(x, y, '%s[%d]' % (path, i))
            if r: return r
        return None
    if type(a) is not type(b):
        return '%s type %r(%s) vs %r(%s)' % (path, a, type(a).__name__, b, type(b).__name__)
    if a != b:
        return '%s %r vs %r' % (path, a, b)
    return None

def compare(data, label):
    expect = ref.run_json(data)
    got = candidate_out(data)
    if expect.startswith('{"error"') or got.startswith('{"error"'):
        if expect != got.strip():
            print('MISMATCH %s: ref=%s cand=%s' % (label, expect[:200], got[:200]))
            return False
        return True
    e = json.loads(expect); g = json.loads(got)
    r = diff(e, g)
    if r:
        print('MISMATCH %s: %s' % (label, r))
        print('   ref ', json.dumps(e)[:300])
        print('   cand', json.dumps(g)[:300])
        return False
    return True

def stats(data, out):
    try:
        j = json.loads(out)
    except Exception:
        return 'error'
    if 'error' in j:
        return 'error'
    acc = rej = stale = 0
    for s in j['sessions']:
        for t in s['transactions']:
            if t['violations'] is None: stale += 1
            elif t['accepted']: acc += 1
            else: rej += 1
    return 'acc=%d rej=%d stale=%d sess=%d' % (acc, rej, stale, len(j['sessions']))

def run_seeds(seeds, kwargs=None, trials=1, verbose=False):
    kwargs = kwargs or {}
    fails = 0
    tally = {}
    rng = random.Random(99)
    for seed in seeds:
        for trial in range(trials):
            try:
                request = gen.build_request(seed * 1000 + trial, **kwargs)
            except (gen.Bad, IndexError, ZeroDivisionError) as exc:
                continue
            data = json.dumps(request, separators=(',', ':'))
            # oracle warm-up passes to make revisions mostly live
            for _ in range(2):
                out = ref.run_json(data)
                if out.startswith('{"error"'):
                    if kwargs.get('force_bad'):
                        break
                    print('UNEXPECTED INVALID seed=%d' % seed)
                    print(data[:1500])
                    fails += 1
                    out = None
                    break
                jreq = json.loads(data)
                gen.adjust_revisions(jreq, json.loads(out), match=0.85, rng=rng)
                data = json.dumps(jreq, separators=(',', ':'))
            if data is None:
                continue
            ok = compare(data, 'seed=%d trial=%d' % (seed, trial))
            if not ok:
                with open('/workspace/dev/fail.json', 'w') as fh:
                    fh.write(data)
                fails += 1
            else:
                if verbose:
                    s = stats(data, ref.run_json(data))
                    for part in s.split():
                        k = part.split('=')[0]
                        tally[k] = tally.get(k, 0) + int(part.split('=')[1]) if '=' in part else 0
    return fails, tally

if __name__ == '__main__':
    lo = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    hi = int(sys.argv[2]) if len(sys.argv) > 2 else 60
    fails, tally = run_seeds(range(lo, hi), verbose=True)
    print('fails=%d' % fails, tally)
